{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "유기동물 발견 신고를 받은 구청장이 구조·보호 조치를 해야 하는 시점",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "구청장은 유기동물 또는 피학대동물을 발견하거나 유기동물 또는 피학대동물의 발견신고를 받은 때에는 이를 지체없이 구조·보호할 수 있도록 필요한 조치를 하여야 한다.",
          "b_ids": "동물보호:제10조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "구조 후 동물정보시스템 공고 시 최소 공고 기간",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "구청장은 제10조제1항에 따라 유기동물을 구조하여 보호조치한 때에는 동물정보시스템에 시행규칙 별지 제12호서식의 공고문을 작성하여 7일 이상 공고하여야 한다.",
          "b_ids": "동물보호:제11조"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
